INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Welcher Constraint in "CREATE TABLE users (id INT PRIMARY KEY)" sichert die Eindeutigkeit?', 2, '[{"text": "PRIMARY KEY", "correct": true, "because": "Garantiert eindeutige Werte"}, {"text": "NOT NULL", "correct": false, "because": "Nur Nicht-Null"}, {"text": "UNIQUE", "correct": false, "because": "Ähnlich, aber nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Was bewirkt "ALTER TABLE employees ADD CONSTRAINT pk_emp PRIMARY KEY (emp_id)"?', 3, '[{"text": "emp_id wird eindeutig und nicht null", "correct": true, "because": "PRIMARY KEY erzwingt beides"}, {"text": "emp_id kann null sein", "correct": false, "because": "PRIMARY KEY erlaubt kein NULL"}, {"text": "Tabelle wird gelöscht", "correct": false, "because": "Nur Strukturänderung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Befehl fügt einen Fremdschlüssel zu "orders" hinzu? "ALTER TABLE orders ADD CONSTRAINT fk_cust FOREIGN KEY (cust_id) REFERENCES customers(id)"?', 4, '[{"text": "fk_cust", "correct": true, "because": "Verknüpft orders mit customers"}, {"text": "PRIMARY KEY", "correct": false, "because": "Falscher Constraint"}, {"text": "CHECK", "correct": false, "because": "Prüft Bedingungen"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert bei "CREATE TABLE products (code VARCHAR(10) UNIQUE)"?', 2, '[{"text": "code darf keine Duplikate enthalten", "correct": true, "because": "UNIQUE erzwingt Eindeutigkeit"}, {"text": "code muss nicht null sein", "correct": false, "because": "UNIQUE erfordert kein NOT NULL"}, {"text": "code wird Primärschlüssel", "correct": false, "because": "UNIQUE ≠ PRIMARY KEY"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Constraint in "CREATE TABLE employees (age INT CHECK (age >= 18))" prüft Werte?', 3, '[{"text": "CHECK", "correct": true, "because": "Prüft Bedingung bei Eingabe"}, {"text": "NOT NULL", "correct": false, "because": "Nur Nullprüfung"}, {"text": "FOREIGN KEY", "correct": false, "because": "Verknüpfung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was bewirkt "ALTER TABLE users ADD CONSTRAINT nn_name NOT NULL (name)"?', 2, '[{"text": "Syntaxfehler", "correct": true, "because": "NOT NULL ist kein eigenständiger Constraint"}, {"text": "name darf nicht null sein", "correct": false, "because": "Falsche Syntax"}, {"text": "name wird eindeutig", "correct": false, "because": "Kein UNIQUE"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Befehl setzt einen Primärschlüssel in "CREATE TABLE dept (id INT, name VARCHAR(50), CONSTRAINT pk_dept PRIMARY KEY (id))"?', 4, '[{"text": "pk_dept", "correct": true, "because": "Definiert Primärschlüssel"}, {"text": "UNIQUE", "correct": false, "because": "Anderer Constraint"}, {"text": "CHECK", "correct": false, "because": "Prüft Bedingungen"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert bei "ALTER TABLE orders DROP CONSTRAINT fk_cust" nach "FOREIGN KEY (cust_id) REFERENCES customers(id)"?', 3, '[{"text": "Fremdschlüssel wird entfernt", "correct": true, "because": "DROP löscht Constraint"}, {"text": "cust_id wird Primärschlüssel", "correct": false, "because": "Keine Neudefinition"}, {"text": "Tabelle wird gelöscht", "correct": false, "because": "Nur Constraint betroffen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Constraint in "CREATE TABLE items (price DECIMAL CHECK (price > 0))" sichert positive Werte?', 5, '[{"text": "CHECK", "correct": true, "because": "Prüft Wertebereich"}, {"text": "PRIMARY KEY", "correct": false, "because": "Nur Eindeutigkeit"}, {"text": "NOT NULL", "correct": false, "because": "Nur Nullprüfung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was bewirkt "CREATE TABLE projects (proj_id INT UNIQUE, name VARCHAR(50))"?', 2, '[{"text": "proj_id hat keine Duplikate", "correct": true, "because": "UNIQUE erzwingt Eindeutigkeit"}, {"text": "proj_id ist Primärschlüssel", "correct": false, "because": "UNIQUE ≠ PRIMARY KEY"}, {"text": "name darf nicht null sein", "correct": false, "because": "Kein NOT NULL"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Befehl fügt einen Constraint hinzu? "ALTER TABLE employees ADD CONSTRAINT fk_dept FOREIGN KEY (dept_id) REFERENCES dept(id)"?', 3, '[{"text": "fk_dept", "correct": true, "because": "Verknüpft mit dept"}, {"text": "CHECK", "correct": false, "because": "Prüft Bedingungen"}, {"text": "UNIQUE", "correct": false, "because": "Eindeutigkeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert bei "CREATE TABLE users (email VARCHAR(50) UNIQUE NOT NULL)"?', 4, '[{"text": "email ist eindeutig und nicht null", "correct": true, "because": "UNIQUE und NOT NULL kombiniert"}, {"text": "email kann null sein", "correct": false, "because": "NOT NULL verhindert das"}, {"text": "email wird Fremdschlüssel", "correct": false, "because": "Kein FOREIGN KEY"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Constraint in "CREATE TABLE sales (id INT, qty INT CHECK (qty > 0))" prüft die Menge?', 2, '[{"text": "CHECK", "correct": true, "because": "Sichert positive Werte"}, {"text": "PRIMARY KEY", "correct": false, "because": "Nur Eindeutigkeit"}, {"text": "FOREIGN KEY", "correct": false, "because": "Verknüpfung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was bewirkt "ALTER TABLE products ADD CONSTRAINT uq_code UNIQUE (code)"?', 3, '[{"text": "code wird eindeutig", "correct": true, "because": "UNIQUE erzwingt Eindeutigkeit"}, {"text": "code wird Primärschlüssel", "correct": false, "because": "UNIQUE ≠ PRIMARY KEY"}, {"text": "code kann null sein", "correct": false, "because": "UNIQUE erfordert kein NOT NULL"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Befehl setzt eine Bedingung? "CREATE TABLE orders (total DECIMAL, CONSTRAINT chk_total CHECK (total >= 0))"?', 4, '[{"text": "chk_total", "correct": true, "because": "Prüft nicht-negative Werte"}, {"text": "NOT NULL", "correct": false, "because": "Nur Nullprüfung"}, {"text": "FOREIGN KEY", "correct": false, "because": "Verknüpfung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert bei "ALTER TABLE employees DROP CONSTRAINT pk_emp" nach "PRIMARY KEY (emp_id)"?', 3, '[{"text": "Primärschlüssel wird entfernt", "correct": true, "because": "DROP löscht Constraint"}, {"text": "emp_id wird nullbar", "correct": false, "because": "Nur wenn NOT NULL fehlt"}, {"text": "Tabelle wird gelöscht", "correct": false, "because": "Nur Constraint betroffen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Constraint in "CREATE TABLE tasks (task_id INT PRIMARY KEY, status VARCHAR(10) NOT NULL)" sichert Nicht-Null?', 2, '[{"text": "NOT NULL", "correct": true, "because": "Verhindert leere Werte"}, {"text": "PRIMARY KEY", "correct": false, "because": "Eindeutigkeit"}, {"text": "CHECK", "correct": false, "because": "Bedingungsprüfung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was bewirkt "CREATE TABLE dept (id INT, mgr_id INT, CONSTRAINT fk_mgr FOREIGN KEY (mgr_id) REFERENCES dept(id))"?', 5, '[{"text": "mgr_id verweist auf id in derselben Tabelle", "correct": true, "because": "Selbstreferenz"}, {"text": "mgr_id wird Primärschlüssel", "correct": false, "because": "Nur Fremdschlüssel"}, {"text": "id wird nullbar", "correct": false, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Befehl fügt eine Eindeutigkeitsregel hinzu? "ALTER TABLE users ADD CONSTRAINT uq_email UNIQUE (email)"?', 3, '[{"text": "uq_email", "correct": true, "because": "Sichert eindeutige Emails"}, {"text": "CHECK", "correct": false, "because": "Prüft Bedingungen"}, {"text": "FOREIGN KEY", "correct": false, "because": "Verknüpfung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert bei "CREATE TABLE inventory (item_id INT PRIMARY KEY, stock INT CHECK (stock >= 0))"?', 4, '[{"text": "item_id eindeutig, stock nicht negativ", "correct": true, "because": "Kombinierte Constraints"}, {"text": "stock wird Primärschlüssel", "correct": false, "because": "Nur item_id"}, {"text": "item_id kann null sein", "correct": false, "because": "PRIMARY KEY verhindert das"}]');
